"""Hash and package generated bytes with explicit simulator-only status."""
from pathlib import Path
import hashlib,json,zipfile
r=Path(__file__).resolve().parents[1];out=r/'out'
files={'cpm-plus-1715.img':out/'cpm-plus-1715.img','CPM3.SYS':r/'build/cpm3.sys','platform.bin':r/'build/platform.cim','memory-map.json':r/'build/system-map.json','README.md':r/'README.md','NOTICE.md':r/'NOTICE.md','LICENSE':r/'LICENSE','JUKU-LICENSE':r/'third_party/JUKU-LICENSE','CPM-LICENSE.md':r/'third_party/cpm3/LICENSE.md'}
for p in (r/'reports').glob('*.json'):files['reports/'+p.name]=p
manifest={'schema':1,'hardware_executed':False,'status':'simulation qualification only','dependencies':json.loads((r/'dependencies.json').read_text()),'files':{n:hashlib.sha256(p.read_bytes()).hexdigest() for n,p in files.items()}}
(out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');files['manifest.json']=out/'manifest.json'
with zipfile.ZipFile(out/'cpm-plus-1715-simulator.zip','w',compression=zipfile.ZIP_DEFLATED) as z:
 for n,p in sorted(files.items()):
  info=zipfile.ZipInfo(n,(2026,1,1,0,0,0));info.compress_type=zipfile.ZIP_DEFLATED;info.external_attr=0o100644<<16;z.writestr(info,p.read_bytes())
print(out/'cpm-plus-1715-simulator.zip')
